// Optional English singular forms travel in the same vocabulary as the messages.
// Russian counters use a noun label ("Символов: 1") and need no suffix assembly.
var uiCountOne = map[string]string{
	"{0} symbols": "{0} symbol", "{0} groups": "{0} group", "{0} parts": "{0} part",
	"{0} components": "{0} component", "{0} connections": "{0} connection", "{0} terms": "{0} term",
	"{0} operations": "{0} operation", "{0} files": "{0} file", "{0} markers": "{0} marker",
	"{0} days ago": "{0} day ago", "{0} imported packages": "{0} imported package",
}

var uiParameter = regexp.MustCompile(`\{([0-9]+)\}`)

func uiVocabulary(language DisplayLanguage) (map[string]string, error) {
	if language == "" {
		language = English
	}
	if language != English && language != Russian {
		return nil, fmt.Errorf("report: unsupported display language %q", language)
	}
	result := make(map[string]string, len(russianUI))
	for key, translated := range russianUI {
		if language == English {
			result[key] = key
		} else {
			result[key] = translated
		}
	}
	for key, one := range uiCountOne {
		if language == English {
			result[key+".one"] = one
		} else {
			result[key+".one"] = russianUI[key]
		}
	}
	return result, nil
}

func uiText(language DisplayLanguage, key string, params ...any) (string, error) {
	translated, known := russianUI[key]
	if !known {
		return "", fmt.Errorf("report: unknown UI message %q", key)
	}
	if language == English || language == "" {
		translated = key
	} else if language != Russian {
		return "", fmt.Errorf("report: unsupported display language %q", language)
	}
	if (language == English || language == "") && len(params) > 0 && fmt.Sprint(params[0]) == "1" {
		if one, ok := uiCountOne[key]; ok {
			translated = one
		}
	}
	used := make([]bool, len(params))
	var invalid bool
	text := uiParameter.ReplaceAllStringFunc(translated, func(token string) string {
		index, err := strconv.Atoi(token[1 : len(token)-1])
		if err != nil || index >= len(params) {
			invalid = true
			return token
		}
		used[index] = true
		return fmt.Sprint(params[index])
	})
	for _, present := range used {
		if !present {
			invalid = true
		}
	}
	if invalid {
		return "", fmt.Errorf("report: UI message %q has mismatched parameters", key)
	}
	return text, nil
}

// englishUI applies the ordinary vocabulary only to a caller-owned UI field.
// The caller identifies those fields; this never walks arbitrary report text.
func englishUI(language DisplayLanguage, text string) string {
	if language == Russian {
		if translated, ok := russianUI[text]; ok {
			return translated
		}
	}
	return text
}
